  "html": "<section class=\"sk-block sk-departments1\" group=\"Features\" data-bs-version=\"5.1\">\n\n    <mbr-parameters>\n    <!-- Block parameters controls (Blue \"Gear\" panel) -->\n        <input type=\"range\" inline title=\"Top\" name=\"paddingTop\" min=\"0\" max=\"9\" step=\"1\" value=\"6\">\n        <input type=\"range\" inline title=\"Bottom\" name=\"paddingBottom\" min=\"0\" max=\"9\" step=\"1\" value=\"6\">\n        <input type=\"checkbox\" title=\"Show Title\" name=\"showTitle\" checked>\n        <input type=\"checkbox\" title=\"Show Subtitle\" name=\"showSubtitle\" checked>\n        <input type=\"range\" inline title=\"Departments\" name=\"deptCount\" min=\"2\" max=\"6\" step=\"1\" value=\"4\">\n        <input type=\"color\" title=\"Background Color\" name=\"bgColor\" value=\"#ffffff\">\n    <!-- End block parameters -->\n    </mbr-parameters>\n\n    <div class=\"container\">\n        <div class=\"row justify-content-center mb-5 text-center\">\n            <div class=\"col-12 col-lg-8\">\n                <h2 class=\"sk-title mbr-section-title mb-3 mbr-fonts-style\" mbr-theme-style=\"display-2\" mbr-if=\"showTitle\">Our teams</h2>\n                <h3 class=\"sk-subtitle mbr-section-subtitle mbr-fonts-style\" mbr-theme-style=\"display-5\" mbr-if=\"showSubtitle\" data-app-selector=\".mbr-section-subtitle\">Who does what.</h3>\n            </div>\n        </div>\n        <div class=\"row g-4\">\n            <div class=\"col-12 col-md-6\">\n                <h4 class=\"sk-dept-title mbr-fonts-style\" mbr-theme-style=\"display-7\" data-app-selector=\".sk-dept-title\">ACCOUNTING</h4>\n                <p class=\"mbr-text mbr-fonts-style\" mbr-theme-style=\"display-7\" data-app-selector=\".mbr-text\">One short paragraph describing what this team does and why it matters.</p>\n            </div>\n            <div class=\"col-12 col-md-6\">\n                <h4 class=\"sk-dept-title mbr-fonts-style\" mbr-theme-style=\"display-7\" data-app-selector=\".sk-dept-title\">SAFETY</h4>\n                <p class=\"mbr-text mbr-fonts-style\" mbr-theme-style=\"display-7\" data-app-selector=\".mbr-text\">One short paragraph describing what this team does and why it matters.</p>\n            </div>\n            <div class=\"col-12 col-md-6\" mbr-if=\"deptCount > 2\">\n                <h4 class=\"sk-dept-title mbr-fonts-style\" mbr-theme-style=\"display-7\" data-app-selector=\".sk-dept-title\">STAGE</h4>\n                <p class=\"mbr-text mbr-fonts-style\" mbr-theme-style=\"display-7\" data-app-selector=\".mbr-text\">One short paragraph describing what this team does and why it matters.</p>\n            </div>\n            <div class=\"col-12 col-md-6\" mbr-if=\"deptCount > 3\">\n                <h4 class=\"sk-dept-title mbr-fonts-style\" mbr-theme-style=\"display-7\" data-app-selector=\".sk-dept-title\">TECHNOLOGY</h4>\n                <p class=\"mbr-text mbr-fonts-style\" mbr-theme-style=\"display-7\" data-app-selector=\".mbr-text\">One short paragraph describing what this team does and why it matters.</p>\n            </div>\n            <div class=\"col-12 col-md-6\" mbr-if=\"deptCount > 4\">\n                <h4 class=\"sk-dept-title mbr-fonts-style\" mbr-theme-style=\"display-7\" data-app-selector=\".sk-dept-title\">LOGISTICS</h4>\n                <p class=\"mbr-text mbr-fonts-style\" mbr-theme-style=\"display-7\" data-app-selector=\".mbr-text\">One short paragraph describing what this team does and why it matters.</p>\n            </div>\n            <div class=\"col-12 col-md-6\" mbr-if=\"deptCount > 5\">\n                <h4 class=\"sk-dept-title mbr-fonts-style\" mbr-theme-style=\"display-7\" data-app-selector=\".sk-dept-title\">COMMUNICATION</h4>\n                <p class=\"mbr-text mbr-fonts-style\" mbr-theme-style=\"display-7\" data-app-selector=\".mbr-text\">One short paragraph describing what this team does and why it matters.</p>\n            </div>\n        </div>\n    </div>\n\n    <style>:root{--sk-navy: #080866; --sk-sky: #38bdf5; --sk-red: #e30512; --sk-ice: #b5cce8; --sk-ice-2: #dce7f5; --sk-ice-3: #f2f7fa; --sk-ink: #111; --sk-muted: #5c6370; --sk-white: #fff; --sk-r-sm: 10px; --sk-r-md: 14px; --sk-r-lg: 18px; --sk-r-pill: 64px; --sk-font-title: \"Shrikhand\", \"Inter\", sans-serif; --sk-font-body: \"Inter\", system-ui, sans-serif; --sk-shadow: 0 8px 24px rgba(8, 8, 102, .12);}.sk-block{font-family: var(--sk-font-body); color: var(--sk-ink); position: relative;}.sk-block .sk-title{font-family: var(--sk-font-title); color: var(--sk-navy); font-weight: 400; line-height: 1.05;}.sk-block .sk-subtitle{color: var(--sk-muted);}.sk-block :focus-visible{outline: 2px solid var(--sk-navy); outline-offset: 2px;}.sk-block .mbr-overlay{position: absolute; inset: 0; pointer-events: none;}.sk-block > .container,.sk-block > .container-fluid{position: relative; z-index: 1;}.sk-dept-title{font-weight: 700; letter-spacing: .04em; color: var(--sk-navy);}</style>\n</section>\n"
